(() => {
  'use strict';
  const M=window.Miam,E=M.esc,F=M.money,$=s=>document.querySelector(s),detail=$('#detail-dialog'),search=$('#search-dialog'),cart=$('#cart-dialog');let focus,heroIndex=0;
  function open(d){focus=document.activeElement;document.querySelectorAll('dialog[open]').forEach(x=>x.close());d.showModal();}
  function notify(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
  document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close-dialog').onclick=()=>d.close();d.addEventListener('close',()=>{if(focus?.isConnected)focus.focus({preventScroll:true});});d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close();});});
  const markup=p=>`<button class="menu-item" data-dish="${p.id}" aria-label="Voir ${E(p.name)}"><img src="assets/${E(p.image)}" alt="" width="78" height="78" loading="lazy"><div><div class="menu-item-heading"><h3>${E(p.name.toUpperCase())}</h3><span class="price">${F(p.price)}</span></div><p>${E(p.description)}</p><span class="dish-availability">${p.available?(p.daily?'AU MENU DU JOUR':'DÉCOUVRIR →'):'ÉPUISÉ POUR LE MOMENT'}</span></div></button>`;
  function renderMenu(){const ps=M.activeProducts();$('#menu-left').innerHTML=ps.slice(0,5).map(markup).join('');$('#menu-right').innerHTML=ps.slice(5,10).map(markup).join('');}
  function showDish(id){const p=M.activeProducts().find(p=>p.id===id);if(!p)return;$('#detail-content').innerHTML=`<img class="detail-image" src="assets/${E(p.image)}" alt="${E(p.name)}"><h2>${E(p.name.toUpperCase())}</h2><p>${E(p.description)}</p><span class="price">${F(p.price)}</span><button class="button" data-add="${p.id}" ${p.available?'':'disabled'}>${p.available?'AJOUTER AU PANIER':'ÉPUISÉ POUR LE MOMENT'}</button>`;open(detail);}
  function renderCart(){const ps=M.cartLines();$('.cart-count').textContent=ps.reduce((n,p)=>n+p.quantity,0);$('#cart-items').innerHTML=ps.length?ps.map(p=>`<article class="cart-item"><img src="assets/${E(p.image)}" alt=""><div><h3>${E(p.name)}</h3><p>${F(p.price)}</p><div class="quantity"><button data-qty="${p.id}" data-value="${p.quantity-1}" aria-label="Retirer une portion de ${E(p.name)}">−</button><span>${p.quantity}</span><button data-qty="${p.id}" data-value="${p.quantity+1}" aria-label="Ajouter une portion de ${E(p.name)}">+</button></div></div><button class="remove-item" data-qty="${p.id}" data-value="0" aria-label="Retirer ${E(p.name)}">×</button></article>`).join(''):'<p>Votre panier est vide. Découvrez les plats de la carte.</p>';$('#cart-total').textContent=F(ps.reduce((n,p)=>n+p.price*p.quantity,0));}
  function renderSearch(q=''){const ps=M.activeProducts().filter(p=>`${p.name} ${p.description}`.toLowerCase().includes(q.trim().toLowerCase()));$('#search-results').innerHTML=ps.length?ps.map(p=>`<button class="search-result" data-dish="${p.id}"><img src="assets/${E(p.image)}" alt=""><span>${E(p.name)}</span><strong>${F(p.price)}</strong></button>`).join(''):'<p>Aucun plat trouvé. Essayez « pizza », « burger » ou « mangue ».</p>';}
  document.addEventListener('click',e=>{const d=e.target.closest('[data-dish]'),a=e.target.closest('[data-add]'),q=e.target.closest('[data-qty]');try{if(d)showDish(d.dataset.dish);if(a){M.addToCart(a.dataset.add);renderCart();detail.close();notify('Ajouté à votre panier.');}if(q){M.setQuantity(q.dataset.qty,Number(q.dataset.value));renderCart();}}catch(error){notify(error.message);}});
  $('[data-open-cart]').onclick=()=>{renderCart();open(cart);};$('#cart-continue').onclick=()=>{location.href=M.current()?.role==='etudiant'?'etudiant.html#panier':'connexion.html';};
  $('[data-open-search]').onclick=()=>{$('#menu-search').value='';renderSearch();open(search);$('#menu-search').focus();};$('#menu-search').oninput=e=>renderSearch(e.target.value);
  const toggle=$('.mobile-toggle'),nav=$('#mobile-nav');function closeNav(){nav.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Ouvrir la navigation');}toggle.onclick=()=>{nav.hidden=!nav.hidden;toggle.setAttribute('aria-expanded',String(!nav.hidden));toggle.setAttribute('aria-label',nav.hidden?'Ouvrir la navigation':'Fermer la navigation');};nav.querySelectorAll('a').forEach(a=>a.onclick=closeNav);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav();});
  function hero(n){heroIndex=(heroIndex+n+2)%2;$('.hero-photo').style.backgroundImage=`linear-gradient(#0008,#0006),url('assets/${['hero-burger.jpeg','hero-burger-alt.jpeg'][heroIndex]}')`;}$('[data-hero-prev]').onclick=()=>hero(-1);$('[data-hero-next]').onclick=()=>hero(1);
  document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>{const img=b.querySelector('img');$('#detail-content').innerHTML=`<img class="detail-image" src="assets/${E(b.dataset.gallery)}" alt="${E(img.alt)}"><h2>${E(img.alt.toUpperCase())}</h2>`;open(detail);});
  const community=['Entre deux cours, après une longue journée ou juste pour le plaisir : il y a toujours une bonne raison de se retrouver autour d’un repas.','Vos petites habitudes méritent de belles attentions. À chaque commande terminée, des points s’ajoutent à votre carte de fidélité.','Les bonnes adresses se partagent. Invitez un ami avec votre code et retrouvez votre bonus après sa première commande terminée.'];document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-review]').forEach(d=>{d.classList.toggle('selected',d===b);d.setAttribute('aria-pressed',String(d===b));});$('#community-copy').textContent=community[Number(b.dataset.review)];});
  const stories=[['Une pause burger entre deux cours','Composez votre repas depuis la carte, indiquez votre heure d’arrivée et retrouvez la préparation dans votre espace étudiant.','discovering-deliciousness-one-recipe-at-a-time.png'],['Les amis, la table et vous','Une table, des amis et le temps de savourer. Retrouvez les rendez-vous du restaurant et partagez votre code de parrainage depuis votre espace.','indulge-in-delicious-creations.png'],['Le plaisir de découvrir de nouvelles saveurs','Les suggestions du jour évoluent avec les envies du restaurant. Consultez les disponibilités avant de composer votre repas.','painting-palates-with-flavorful-delights.png']];document.querySelectorAll('[data-blog]').forEach(b=>b.onclick=()=>{const [title,copy,img]=stories[Number(b.dataset.blog)];$('#detail-content').innerHTML=`<img class="detail-image" src="assets/${img}" alt=""><h2>${title.toUpperCase()}</h2><p>${copy}</p><a class="button" href="connexion.html">DÉCOUVRIR MON ESPACE →</a>`;open(detail);});
  const form=$('#reservation-form');form.elements.date.min=new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Kinshasa'});form.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form));$('#reservation-status').textContent=`Simulation pour ${v.name} : ${v.guests} personne(s), le ${M.date(v.date)}, ${v.time}. Aucune réservation n’a été envoyée au restaurant.`;};
  const u=M.current();if(u)document.querySelectorAll('[data-account-link]').forEach(a=>{a.textContent='Mon espace';a.href=`${u.role}.html`;});try{$('#cookie-note').hidden=localStorage.getItem('miam-storage-notice')==='yes';}catch{$('#cookie-note').hidden=false;}$('#cookie-dismiss').onclick=()=>{$('#cookie-note').hidden=true;try{localStorage.setItem('miam-storage-notice','yes');}catch{}};
  const strip=$('.instagram-strip'),track=$('.gallery-track'),motionButton=$('.gallery-motion-toggle');
  if(track){
    const duplicate=track.firstElementChild.cloneNode(true);duplicate.setAttribute('aria-hidden','true');duplicate.inert=true;track.append(duplicate);
    let paused=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
    const syncMotion=()=>{strip.classList.toggle('motion-paused',paused);motionButton.hidden=reduced.matches;motionButton.setAttribute('aria-pressed',String(paused));motionButton.innerHTML=paused?'Reprendre le défilement <span aria-hidden="true">▶</span>':'Mettre en pause <span aria-hidden="true">Ⅱ</span>';};
    motionButton.addEventListener('click',()=>{paused=!paused;syncMotion();});reduced.addEventListener('change',syncMotion);syncMotion();
  }
  renderMenu();renderCart();window.addEventListener('storage',e=>{if(e.key===M.KEY){renderMenu();renderCart();}});
})();
